/bin/bash -lc "find . -maxdepth 2 -type f -printf '%p\\n' | sort && printf '\\n--- tools ---\\n' && command -v ffmpeg && command -v python3 && python3 - <<'PY'
try:
 import cv2; print('cv2',cv2.__version__)
except Exception as e: print('no cv2',e)
try:
 from PIL import Image; print('PIL ok')
except Exception as e: print('no PIL',e)
PY"

/bin/bash -lc 'for c in ffmpeg python3 convert; do printf "$c: "; command -v $c || true; done; python3 - <<'"'PY'
mods=['cv2','PIL','numpy','imageio','scipy']
for m in mods:
 try:
  x=__import__(m); print(m,getattr(x,'__version__','ok'))
 except Exception as e: print(m,'NO',e)
